// Validate voice request
const data = items[0].json;
if (!data.text || typeof data.text !== 'string' || data.text.trim().length === 0) {
  return [{ json: { error: 'Missing or empty text for TTS', status: 'error' } }];
}
if (!data.language) {
  return [{ json: { error: 'Missing language parameter', status: 'error' } }];
}
const lang = data.language;
const langCode = lang.slice(0, 2) + '-' + lang.slice(3); // en-US -> en-US
return [{
  json: {
    text: data.text.trim(),
    language: lang,
    language_code: langCode,
    voice_name: data.voice_name || 'en-US-Standard-A',
    pitch: data.pitch || 1.0,
    speaking_rate: data.speaking_rate || 1.0,
    session_id: data.session_id || 'unknown',
  }
}];

// Extract audio content from TTS response
const data = items[0].json;
const audioContent = data.audioContent;

if (!audioContent) {
  return [{
    json: {
      status: 'tts_failed',
      audio_base64: null,
      error: 'TTS API returned no audio content',
      fallback: true,
      text: items[0].json.text,
    }
  }];
}

return [{
  json: {
    status: 'ok',
    audio_base64: audioContent,
    audio_format: 'mp3',
    text: items[0].json.text,
    language: items[0].json.language,
  }
}];
